param([Parameter(Mandatory=$true)][int]$ProcessId,[Parameter(Mandatory=$true)][string]$DocumentTitle,[Parameter(Mandatory=$true)][string]$MenuText,[string]$Log='temp/cubism-menu-invoke.txt')
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$source=Join-Path $PSScriptRoot 'cubism_bridge';$jdk=Join-Path $root 'temp\jdk17\jdk-17.0.20+8\bin';$classes=Join-Path $root 'temp\cubism-menu-invoke-agent\classes';$hash=(Get-FileHash (Join-Path $source 'CubismMenuInvokeAgent.java') -Algorithm SHA256).Hash.Substring(0,12).ToLowerInvariant();$jar=Join-Path $root "temp\cubism-menu-invoke-agent-$hash.jar";$manifest=Join-Path $root 'temp\cubism-menu-invoke-manifest.mf';$resolved=[IO.Path]::GetFullPath((Join-Path $root $Log));New-Item -ItemType Directory -Force $classes,(Split-Path -Parent $resolved)|Out-Null;if(-not(Test-Path $jar)){@"
Agent-Class: mugi.bridge.CubismMenuInvokeAgent

"@|Set-Content $manifest -Encoding ascii;& (Join-Path $jdk 'javac.exe') -encoding UTF-8 -d $classes (Join-Path $source 'AttachAgent.java') (Join-Path $source 'CubismMenuInvokeAgent.java');if($LASTEXITCODE-ne 0){throw 'javac failed'};& (Join-Path $jdk 'jar.exe') cfm $jar $manifest -C $classes .};& (Join-Path $jdk 'java.exe') --add-modules jdk.attach -cp $classes AttachAgent $ProcessId $jar "$DocumentTitle|$MenuText|$resolved";Start-Sleep -Seconds 2;Get-Content $resolved -Raw
